/* Jalon "notifications push" — à exécuter une seule fois dans l'éditeur SQL*/ /* de Supabase (Project > SQL Editor), APRÈS avoir ajouté les 3 variables*/ /* d'environnement dans Vercel (voir message à côté de ce fichier).*/ /**/ /* Contenu :*/ /* 1. Table push_subscriptions (un abonnement par appareil/navigateur).*/ /* 2. RLS sur cette table.*/ /* 3. Extension pg_net (permet à Postgres d'appeler une URL en HTTP).*/ /* 4. Fonction générique notifier_push() qui appelle l'API de l'appli.*/ /* 5. Trois déclencheurs : nouveau message, nouveau devoir, devoir corrigé.*/ /* 6. Jalon "demandes de compte" : deux déclencheurs supplémentaires*/ /* (nouvelle demande -> admin, demande validée -> demandeur), ajoutés en*/ /* remplacement d'un envoi de SMS (service tiers payant non disponible).*/ /* IMPORTANT (securite) : ce fichier ne doit jamais contenir la vraie valeur*/ /* du secret push. Avant d'executer la fonction notifier_push() ci-dessous*/ /* dans l'editeur SQL de Supabase, remplace REMPLACE_PAR_LE_SECRET_VERCEL par*/ /* la valeur reelle de PUSH_WEBHOOK_SECRET (Vercel > Settings > Environment*/ /* Variables), uniquement dans l'editeur SQL -- ne commite jamais cette*/ /* valeur reelle sur GitHub.*/ /* 1. Table des abonnements push -------------------------------------------*/ create table if not exists push_subscriptions ( id uuid primary key default gen_random_uuid(), compte_id uuid references comptes(id) on delete cascade not null, endpoint text not null unique, p256dh text not null, auth text not null, created_at timestamptz not null default now() ); alter table push_subscriptions enable row level security; create policy "un compte gere ses propres abonnements push" on push_subscriptions for all using (compte_id = auth.uid()) with check (compte_id = auth.uid()); /* 2. pg_net : permet à une fonction Postgres d'appeler une URL en HTTP -----*/ create extension if not exists pg_net; /* 3. Fonction générique d'envoi ---------------------------------------------*/ create or replace function notifier_push(p_compte_ids uuid[], p_titre text, p_corps text, p_url text default '/') returns void language plpgsql security definer as $$ begin if p_compte_ids is null or array_length(p_compte_ids, 1) is null then return; end if; perform net.http_post( url := 'https://application-revision.vercel.app/api/push/envoyer', headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', 'REMPLACE_PAR_LE_SECRET_VERCEL'), body := jsonb_build_object('compteIds', to_jsonb(p_compte_ids), 'titre', p_titre, 'corps', p_corps, 'url', p_url) ); end; $$; /* 4. Déclencheur : nouveau message -----------------------------------------*/ /* Notifie tout le monde dans le fil de la famille (parent(s), soutien(s),*/ /* admin) sauf l'auteur du message ; ou uniquement le destinataire choisi si*/ /* le message est adressé à quelqu'un en particulier.*/ create or replace function trig_notifier_nouveau_message() returns trigger language plpgsql security definer as $$ declare v_destinataires uuid[]; begin if new.destinataire_id is not null then if new.destinataire_id <> new.auteur_id then v_destinataires := array[new.destinataire_id]; end if; else select array_agg(distinct id) into v_destinataires from ( select parent_id as id from liens_parent_enfant where enfant_id = new.enfant_id union select soutien_id as id from liens_soutien where enfant_id = new.enfant_id union select id from comptes where role = 'admin' union select new.enfant_id as id ) t where id <> new.auteur_id; end if; perform notifier_push(v_destinataires, 'Nouveau message', 'Vous avez un nouveau message dans la messagerie.', '/'); return new; end; $$; drop trigger if exists on_nouveau_message_push on messages; create trigger on_nouveau_message_push after insert on messages for each row execute function trig_notifier_nouveau_message(); /* 5. Déclencheur : nouveau devoir -------------------------------------------*/ /* Notifie l'enfant concerné.*/ create or replace function trig_notifier_nouveau_devoir() returns trigger language plpgsql security definer as $$ declare v_matiere text; v_label_type text; begin select nom into v_matiere from matieres where id = new.matiere_id; v_label_type := case new.type when 'revision' then 'Réviser le cours' when 'exercice' then 'Exercices' when 'test' then 'Test' else new.type::text end; perform notifier_push(array[new.enfant_id], 'Nouveau devoir', coalesce(v_matiere || ' · ', '') || v_label_type, '/enfant'); return new; end; $$; drop trigger if exists on_nouveau_devoir_push on devoirs; create trigger on_nouveau_devoir_push after insert on devoirs for each row execute function trig_notifier_nouveau_devoir(); /* 6. Déclencheur : exercice corrigé -----------------------------------------*/ /* Notifie l'enfant dès qu'une note est renseignée pour la première fois.*/ create or replace function trig_notifier_correction() returns trigger language plpgsql security definer as $$ declare v_enfant_id uuid; v_matiere text; begin if old.note is null and new.note is not null then select d.enfant_id, m.nom into v_enfant_id, v_matiere from devoirs d left join matieres m on m.id = d.matiere_id where d.id = new.devoir_id; if v_enfant_id is not null then perform notifier_push(array[v_enfant_id], 'Devoir corrigé', coalesce(v_matiere || ' — ', '') || new.note || '/20', '/enfant'); end if; end if; return new; end; $$; drop trigger if exists on_correction_exercice_push on reponses_exercices; create trigger on_correction_exercice_push after update on reponses_exercices for each row execute function trig_notifier_correction(); /* 7. Déclencheur : nouvelle demande de compte -------------------------------*/ /* Notifie tous les comptes admin des qu'une demande (Parent, Soutien ou*/ /* Co-parent) est deposee.*/ create or replace function trig_notifier_nouvelle_demande() returns trigger language plpgsql security definer as $$ declare v_admins uuid[]; v_label_type text; begin select array_agg(id) into v_admins from comptes where role = 'admin'; v_label_type := case new.type_compte when 'parent' then 'Parent' when 'soutien' then 'Soutien' when 'coparent' then 'Co-parent' else new.type_compte end; perform notifier_push(v_admins, 'Nouvelle demande de compte', v_label_type || ' — ' || coalesce(new.nom, new.email), '/admin'); return new; end; $$; drop trigger if exists on_nouvelle_demande_push on demandes_comptes; create trigger on_nouvelle_demande_push after insert on demandes_comptes for each row execute function trig_notifier_nouvelle_demande(); /* 8. Déclencheur : demande de compte validée --------------------------------*/ /* Notifie le demandeur (le parent a l'origine de la demande) des que*/ /* l'administrateur valide et que le compte est cree. N'a d'effet que pour*/ /* les demandes avec un demandeur_id (Soutien, Co-parent) : une demande de*/ /* compte Parent publique n'a pas encore de compte a notifier a ce stade,*/ /* le demandeur recoit deja l'email d'invitation habituel.*/ create or replace function trig_notifier_demande_validee() returns trigger language plpgsql security definer as $$ declare v_label_type text; begin if old.statut is distinct from 'traitee' and new.statut = 'traitee' and new.demandeur_id is not null then v_label_type := case new.type_compte when 'soutien' then 'soutien' when 'coparent' then 'co-parent' else 'compte' end; perform notifier_push(array[new.demandeur_id], 'Demande validée', 'Le compte ' || v_label_type || ' de ' || coalesce(new.nom, new.email) || ' a été créé.', '/parent'); end if; return new; end; $$; drop trigger if exists on_demande_validee_push on demandes_comptes; create trigger on_demande_validee_push after update on demandes_comptes for each row execute function trig_notifier_demande_validee();
